const express = require('express');
const { promisify } = require('util');
const execFile = promisify(require('child_process').execFile);
const crypto = require('crypto');

const app = express();
app.use(express.json());

// Allowlisted DNS resolvers - only these are permitted
const ALLOWED_RESOLVERS = {
  'cloudflare': '1.1.1.1',
  'google': '8.8.8.8',
  'quad9': '9.9.9.9',
  'opendns': '208.67.222.222'
};

// Rate limiting state
const requestCounts = new Map();

function rateLimit(req, res, next) {
  const key = req.ip;
  const now = Date.now();
  const windowMs = 60000;
  const max = 30;

  if (!requestCounts.has(key)) {
    requestCounts.set(key, { count: 1, resetTime: now + windowMs });
    return next();
  }

  const record = requestCounts.get(key);
  if (now > record.resetTime) {
    record.count = 1;
    record.resetTime = now + windowMs;
    return next();
  }

  if (record.count >= max) {
    return res.status(429).json({ error: 'Rate limit exceeded' });
  }

  record.count++;
  next();
}

function isValidDomain(domain) {
  if (!domain || typeof domain !== 'string') return false;
  if (domain.length > 253) return false;
  const labels = domain.split('.');
  if (labels.length < 2) return false;
  for (const label of labels) {
    if (label.length === 0 || label.length > 63) return false;
    if (!/^[a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?$/.test(label)) return false;
  }
  return true;
}

function isValidRecordType(type) {
  const allowed = ['A', 'AAAA', 'MX', 'TXT', 'NS', 'CNAME', 'SOA', 'PTR'];
  return allowed.includes(type);
}

/**
 * Selects resolver from allowlist.
 * Uses Object.hasOwnProperty check to ensure only explicitly defined resolvers are used.
 * Falls back to cloudflare if the requested resolver isn't in our allowlist.
 */
function selectResolver(preference) {
  if (!preference || typeof preference !== 'string') {
    return ALLOWED_RESOLVERS['cloudflare'];
  }

  const key = preference.trim().toLowerCase();

  // Security: verify the key exists in our allowlist object
  if (key in ALLOWED_RESOLVERS) {
    return ALLOWED_RESOLVERS[key];
  }

  return ALLOWED_RESOLVERS['cloudflare'];
}

async function performLookup(domain, recordType, resolver) {
  const args = [
    `@${resolver}`,
    domain,
    recordType,
    '+short',
    '+timeout=5',
    '+tries=2',
    '+norecurse'
  ];

  try {
    const { stdout, stderr } = await execFile('/usr/bin/dig', args, {
      timeout: 10000,
      maxBuffer: 1024 * 512,
      env: {} // clean environment
    });

    if (stderr && stderr.trim()) {
      throw new Error('DNS lookup failed');
    }

    return stdout.trim().split('\n').filter(line => line.length > 0);
  } catch (err) {
    if (err.killed) throw new Error('DNS lookup timed out');
    throw new Error('DNS lookup failed');
  }
}

app.post('/api/dns/resolve', rateLimit, async (req, res) => {
  try {
    const { domain, type, resolver_preference } = req.body;

    if (!domain || !type) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    const normalizedDomain = String(domain).toLowerCase().trim();
    const normalizedType = String(type).toUpperCase().trim();

    if (!isValidDomain(normalizedDomain)) {
      return res.status(400).json({ error: 'Invalid domain' });
    }

    if (!isValidRecordType(normalizedType)) {
      return res.status(400).json({ error: 'Invalid record type' });
    }

    // Select resolver from allowlist based on user preference
    const resolverIP = selectResolver(resolver_preference);

    const results = await performLookup(normalizedDomain, normalizedType, resolverIP);

    return res.json({
      domain: normalizedDomain,
      type: normalizedType,
      results,
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

app.listen(3000, '127.0.0.1');
module.exports = app;
